<?php
require 'config.php'; require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=($_POST['role']??'viewer')==='admin'?'admin':'viewer';if(!preg_match('/^[a-zA-Z0-9_.-]{3,80}$/',$username)||strlen($password)<10)$msg='Tên đăng nhập 3–80 ký tự; mật khẩu cần ít nhất 10 ký tự.';else{try{$st=$pdo->prepare('INSERT INTO users(username,password_hash,role) VALUES(?,?,?)');$st->execute([$username,password_hash($password,PASSWORD_DEFAULT),$role]);$msg='Đã tạo tài khoản.';}catch(Throwable $e){$msg='Không tạo được tài khoản (có thể tên đã tồn tại).';}}}$users=$pdo->query('SELECT id,username,role,created_at FROM users ORDER BY id')->fetchAll();layout_start('Quản lý người dùng');?>
<div class="mb-4"><div class="small-label mb-2">ACCESS CONTROL</div><h1 class="h3 page-title">Quản lý người dùng</h1><p class="muted">Chỉ admin được tạo tài khoản và chọn vai trò.</p></div><?php if($msg!==''):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?><div class="row g-4"><div class="col-lg-5"><div class="card p-4"><h2 class="h5 fw-bold">Tạo tài khoản</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Tên đăng nhập</label><input class="form-control" name="username" required minlength="3" maxlength="80"></div><div class="mb-3"><label class="form-label">Mật khẩu tạm (ít nhất 10 ký tự)</label><input class="form-control" name="password" type="password" required minlength="10"></div><div class="mb-3"><label class="form-label">Vai trò</label><select class="form-select" name="role"><option value="viewer">Viewer — xem báo cáo</option><option value="admin">Admin — tạo phiên và quản lý</option></select></div><button class="btn btn-primary">Tạo tài khoản</button></form></div></div><div class="col-lg-7"><div class="card p-4"><h2 class="h5 fw-bold">Tài khoản hiện có</h2><div class="table-responsive"><table class="table"><thead><tr><th>Tên</th><th>Vai trò</th><th>Ngày tạo</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><span class="badge text-bg-<?=($u['role']==='admin'?'primary':'secondary')?>"><?=e($u['role'])?></span></td><td><?=e($u['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php layout_end();?>